function storeSessionSnapshot(record,archive=!!(record?.investigation||record?.fieldVisit)){
  const next=structuredClone(record),revision=++sessionSaveRevision;
  if(next?.fieldVisit){next.fieldVisit=sanitizeFieldVisitForStorage(next.fieldVisit);next.unresolved=next.fieldVisit.state!=='closed';}
  else if(next?.investigation)next.unresolved=next.investigation.handover?.status!=='resolved';
  const pending=sessionSaveQueue.catch(()=>{}).then(async()=>{
    const result=archive?await saveCaseSnapshot(next):(await db.setSetting('session',next),{session:next});
    if(result.history)history=result.history;
    if(session?.id===next?.id&&revision===sessionSaveRevision)session=result.session;
    return result;
  });sessionSaveQueue=pending;return pending;
}
