async function transferQuestionJob(conversation){
  await flushVisitEditors();if(session)await storeSessionSnapshot(session,true);
  // Stable ID makes a retry after a failed conversation save reuse the same job.
  const id='questions-'+conversation.id,existing=history.find(item=>item.id===id);
  const next=existing||createQuickFaultTransfer(conversation,{id});
  const result=await saveCaseSnapshot(next);session=result.session;history=result.history;
  freshTerminalSessionId='';pendingTerminalSessionId='';go('#investigation');return session.id;
}

