function renderFaults(){
  if(!session)session=newFieldSession();
  if(pendingTerminalSessionId===session.id){
    if(terminalEntryPromise)return;
    const id=session.id;
    app.innerHTML='<section class="terminal-session"><p role="status">FINDR &gt; Saving your new conversation on this device…</p></section>';
    terminalEntryPromise=storeSessionSnapshot(session).then(()=>{
      if(pendingTerminalSessionId===id)pendingTerminalSessionId='';
      if(session?.id===id&&['#faults','#investigation','#diagnostic'].includes(location.hash)){
        diagnosticChat.render({fresh:freshTerminalSessionId===id});freshTerminalSessionId='';
      }
    }).catch(error=>{
      if(session?.id===id&&['#faults','#investigation','#diagnostic'].includes(location.hash))app.innerHTML=`<section class="terminal-session"><p role="alert">FINDR &gt; I couldn’t save this new conversation. ${esc(error.message||'Device storage is unavailable.')}</p><p>Your previous saved visits are unchanged. Retry when device storage is available.</p>${action('navigate','[ retry save ]','secondary',`data-value="${esc(location.hash)}"`)}</section>`;
      toast('New conversation not saved. Retry when device storage is available.');
    }).finally(()=>{terminalEntryPromise=null;});
    return;
  }
  diagnosticChat.render({fresh:freshTerminalSessionId===session.id});freshTerminalSessionId='';
}
