async function fetchPDF(record,signal,onProgress){
  const response=await fetch('/api/manual/'+encodeURIComponent(record.id),{signal});
  if(!response.ok)throw new Error((await response.text()).slice(0,220)||'Download failed');
  const max=120*1024*1024,total=Number(response.headers.get('content-length')||0);
  if(total>max)throw new Error('File is over 120 MB.');
  const chunks=[];let size=0;
  const report=()=>onProgress?.({message:'Downloading '+record.title+' · '+bytes(size),completed:size,total});
  if(response.body?.getReader){
    const reader=response.body.getReader();
    for(;;){const part=await reader.read();if(part.done)break;size+=part.value.length;if(size>max){await reader.cancel();throw new Error('File is over 120 MB.');}chunks.push(part.value);report();}
  }else{const buffer=await response.arrayBuffer();size=buffer.byteLength;if(size>max)throw new Error('File is over 120 MB.');chunks.push(buffer);report();}
  if(signal?.aborted)throw new DOMException('Download cancelled.','AbortError');const blob=new Blob(chunks,{type:'application/pdf'});
  onProgress?.({message:'Checking '+record.title+' before saving'});
  const hash=await validatePDF(blob,record.sha256);if(signal?.aborted)throw new DOMException('Download cancelled.','AbortError');
  onProgress?.({message:'Saving '+record.title+' on this device'});
  await db.saveManual({...record,bytes:blob.size,savedAt:Date.now(),fileHash:hash,imported:false},blob);
}
async function startDownload(ids,{signal,onProgress}={}){
  if(job?.running){toast('A download is already running.');return {busy:true,saved:0,failed:[],cancelled:false};}
  if(signal?.aborted)return {saved:0,failed:[],cancelled:true};
  const queue=[...new Set(ids)].filter(id=>records.get(id)?.url&&!saved.has(id));
  if(!queue.length){toast('These PDFs are already saved.');return {saved:0,failed:[],cancelled:false};}
  const download={running:true,cancelled:false,total:queue.length,done:0,saved:0,failed:[],current:''};job=download;
  const cancel=()=>{download.cancelled=true;download.controller?.abort();renderJob();};
  signal?.addEventListener('abort',cancel,{once:true});renderJob();
  try{
    for(const id of queue){
      if(download.cancelled)break;
      const record=records.get(id);download.current=record.title;download.controller=new AbortController();renderJob();
      const timer=setTimeout(()=>download.controller.abort(),90000);
      try{await fetchPDF(record,download.controller.signal,onProgress);saved=new Map((await db.allManuals()).map(item=>[item.id,item]));download.saved++;}
      catch(error){if(!download.cancelled)download.failed.push({id,error:error.name==='AbortError'?'Download timed out. Retry on a stronger connection.':error.message,code:/storage|quota/i.test(error.message)||error.name==='QuotaExceededError'?'STORAGE_UNAVAILABLE':typeof error.code==='string'?error.code:'MANUAL_DOWNLOAD_FAILED'});}
      finally{clearTimeout(timer);}
      download.done++;updateStatus();renderJob();
    }
  }finally{signal?.removeEventListener('abort',cancel);download.running=false;download.current='';}
  if(['home','downloads','pack','device-pack'].includes(activeRoute()[0]))render();
  else toast(download.cancelled?'Download cancelled. Previously saved manuals are unchanged.':download.failed.length?'Some PDFs could not be saved. See Downloads.':`${download.saved} PDF${download.saved===1?'':'s'} saved on this device.`);
  renderJob();return download;
}
async function downloadConversationManual(id,options={}){
  if(saved.has(id))return saved.get(id);
  if(!records.get(id)?.url)throw Object.assign(new Error('This catalogue entry has no PDF available to download. Choose another manual or upload your PDF.'),{code:'MANUAL_DOWNLOAD_FAILED'});
  const result=await startDownload([id],options);
  if(saved.has(id))return saved.get(id);
  if(result?.cancelled||options.signal?.aborted)throw new DOMException('The manual download was cancelled. Retry the download when you are ready.','AbortError');
  if(result?.busy)throw Object.assign(new Error('Another manual download is running. Wait for it to finish, then retry.'),{code:'MANUAL_DOWNLOAD_FAILED'});
  const failure=result?.failed?.find(item=>item.id===id);
  throw Object.assign(new Error(failure?.error||'The manual could not be saved. Retry the download or choose another manual.'),{code:failure?.code||'MANUAL_DOWNLOAD_FAILED'});
}

