async function readPDF(id,{page:initialPage=1,returnWiringId=null,notice='',canOpen=null,sourceBlob=null}={}){const r=saved.get(id),blob=sourceBlob||await db.getFile(id);if(canOpen&&!canOpen())return;if(!blob){toast('File not found on this device. Download it again.');return}showModal(`${returnWiringId?action('wiring-view','← Back to wiring picture','secondary wiring-reader-return',`data-id="${esc(returnWiringId)}"`):''}<div class="reader-title">${esc(r?.title||'Saved PDF')}</div>${notice?`<p class="wiring-reader-notice">${esc(notice)}</p>`:''}<div class="reader-controls">${action('pdf-prev','←','secondary','aria-label="Previous page"')}<label class="small">Page <input id="pdf-page" type="number" value="1" min="1" aria-label="PDF page number"></label><span id="pdf-total"></span>${action('pdf-next','→','secondary','aria-label="Next page"')}<span id="pdf-status" class="reader-status">Opening saved PDF…</span></div><div class="reader-find"><input id="pdf-query" placeholder="Find text in this PDF" aria-label="Search PDF text">${action('pdf-search','Find','secondary')}</div><div class="reader-canvas"><canvas id="pdf-canvas"></canvas></div>`,'reader');const token=++readerToken;try{const lib=await loadPDFLibrary();const doc=await lib.getDocument(pdfDocumentOptions(await loadPDFBytes(blob))).promise;if(token!==readerToken){doc.destroy();return}pdfDoc=doc;pdfPage=1;const requestedPage=Number.isInteger(initialPage)&&initialPage>0?initialPage:1;const sourcePageAvailable=requestedPage<=pdfDoc.numPages;$('#pdf-total').textContent='of '+pdfDoc.numPages;$('#pdf-page').max=pdfDoc.numPages;$('#pdf-page').onchange=e=>drawPage(Number(e.target.value));await drawPage(sourcePageAvailable?requestedPage:1);if(!sourcePageAvailable)$('#pdf-status').textContent='Recorded source page is unavailable in this PDF; opened page 1.'}catch(e){if(token===readerToken)$('#pdf-status').textContent='Cannot read this PDF: '+e.message}}
