 if(session.importedContext)rows.push(importedContextReport(session.importedContext));
 const g=group(),observations=g?answerEntries(g,session.answers):[];
 if(observations.length)rows.push('\nRecorded checks',...observations.map(([id,a])=>(g.questions.find(q=>q.id===id)?.text||id)+' '+answerLabel(a)));
